from pathlib import Path

path = Path('src/fusdb/relationsystem.py')
text = path.read_text()

if 'from dataclasses import dataclass' not in text:
    text = text.replace('from collections.abc import Iterable, Mapping, Sequence\n', 'from collections.abc import Iterable, Mapping, Sequence\nfrom dataclasses import dataclass\n')

marker = '\n\nclass CompilePlan:'
idx = text.index(marker)
structure_class = '''\n\n@dataclass(frozen=True)\nclass _CompiledStructure:\n    """Immutable reusable structural result for one supplied/fixed signature."""\n\n    variable_roles: tuple[tuple[str, str], ...]\n    packed_variables: frozenset[str]\n    unseeded_variables: frozenset[str]\n    primary_relations: tuple[Relation, ...]\n    relations: tuple[Relation, ...]\n    constant_defaults: tuple[tuple[str, Any], ...]\n    seeded_defaults: tuple[tuple[str, float], ...]\n    structural_blocks: tuple[tuple[str, ...], ...]\n    determined_missing: tuple[str, ...]\n    undecidable: tuple[str, ...]\n    deficiencies: tuple[tuple[tuple[str, ...], tuple[str, ...], int], ...]\n    active_relation_names: frozenset[str]\n    inactive_reasons: tuple[tuple[str, str], ...]\n    decidability: tuple[tuple[str, str], ...]\n    default_providers: tuple[tuple[str, Relation], ...]\n    derived_providers: tuple[tuple[str, Relation], ...]\n    seed_tape: tuple[Any, ...]\n    seed_tape_names: frozenset[str]\n'''
text = text[:idx] + structure_class + text[idx:]

# Replace direct full compilation at the end of CompilePlan.__init__.
old = '''        # A CompilePlan is compiled by definition. There is no mutable\n        # "uncompiled plan" lifecycle and no public recompile operation.\n        self._compile_with_pruning()\n'''
new = '''        # A CompilePlan is compiled by definition. Reuse an immutable model-owned\n        # structural result when the supplied/fixed signature matches, but always\n        # refresh value-dependent seeds and validate packing against this scenario.\n        self._compile_or_reuse_structure()\n'''
if old not in text:
    raise SystemExit('CompilePlan init final compile block not found')
text = text.replace(old, new, 1)

# Insert cache helpers immediately before the pruning compiler.
needle = '    def _compile_with_pruning(self, max_rounds: int = 20) -> None:\n'
pos = text.index(needle, text.index('class CompilePlan:'))
helpers = '''    @property\n    def structural_fingerprint(self) -> tuple[frozenset[str], frozenset[str]]:\n        return (frozenset(self.inputs), frozenset(self.fixed))\n\n    def _capture_structure(self) -> _CompiledStructure:\n        diagnostics = self._partition_diagnostics\n        deficiencies = tuple(\n            (\n                tuple(item["variables"]),\n                tuple(item["relations"]),\n                int(item["missing_values"]),\n            )\n            for item in diagnostics.get("deficiencies", ())\n        )\n        return _CompiledStructure(\n            variable_roles=tuple(sorted(self.variable_roles.items())),\n            packed_variables=frozenset(self.packed_variables),\n            unseeded_variables=frozenset(self.unseeded_variables),\n            primary_relations=tuple(self.primary_relations),\n            relations=tuple(self.relations),\n            constant_defaults=tuple(sorted(self.constant_default_values.items())),\n            seeded_defaults=tuple(sorted(self.seeded_default_values.items())),\n            structural_blocks=tuple(tuple(block) for block in self.structural_blocks),\n            determined_missing=tuple(diagnostics.get("determined_missing_variables", ())),\n            undecidable=tuple(diagnostics.get("undecidable_variables", ())),\n            deficiencies=deficiencies,\n            active_relation_names=frozenset(self._active_relation_names),\n            inactive_reasons=tuple(sorted(self._inactive_reasons.items())),\n            decidability=tuple(sorted(self._decidability.items())),\n            default_providers=tuple(sorted(self._default_providers.items())),\n            derived_providers=tuple(sorted(self._derived_providers.items())),\n            seed_tape=tuple(self._seed_tape or ()),\n            seed_tape_names=frozenset(self._seed_tape_names),\n        )\n\n    def _restore_structure(self, structure: _CompiledStructure) -> None:\n        self.variable_roles = dict(structure.variable_roles)\n        self.packed_variables = set(structure.packed_variables)\n        self.unseeded_variables = set(structure.unseeded_variables)\n        self.primary_relations = list(structure.primary_relations)\n        self.relations = list(structure.relations)\n        self.constant_default_values = dict(structure.constant_defaults)\n        self.seeded_default_values = dict(structure.seeded_defaults)\n        self.structural_blocks = [tuple(block) for block in structure.structural_blocks]\n        self._partition_diagnostics = {\n            "determined_missing_variables": structure.determined_missing,\n            "undecidable_variables": structure.undecidable,\n            "deficiencies": [\n                {\n                    "variables": list(variables),\n                    "relations": list(relations),\n                    "missing_values": missing,\n                }\n                for variables, relations, missing in structure.deficiencies\n            ],\n        }\n        self._active_relation_names = set(structure.active_relation_names)\n        self._inactive_reasons = dict(structure.inactive_reasons)\n        self._decidability = dict(structure.decidability)\n        self._default_providers = dict(structure.default_providers)\n        self._derived_providers = dict(structure.derived_providers)\n        self._seed_tape = list(structure.seed_tape) or None\n        self._seed_tape_names = set(structure.seed_tape_names)\n        all_relations = [*self.candidate_primary_relations, *self.system_constraint_relations, *self.relations]\n        self.relations_by_name = {rel.name: rel for rel in all_relations}\n        self.relations_by_function = {rel.function_name: rel for rel in all_relations}\n        self._dependency_closure_cache = None\n        self._compiler_report_cache = None\n\n    def _try_cached_structure(self, structure: _CompiledStructure) -> bool:\n        self._restore_structure(structure)\n        self._unevaluable_names = set()\n        self._freeze_execution_plan()\n        self._refresh_seeds()\n        uninitialized, underdetermined = self._packing_issues()\n        if uninitialized or underdetermined:\n            return False\n        self.pack()\n        return True\n\n    def _compile_or_reuse_structure(self) -> None:\n        fingerprint = self.structural_fingerprint\n        cached = self.model._structure_cache.get(fingerprint)\n        if cached is not None:\n            try:\n                if self._try_cached_structure(cached):\n                    self._structure_cache_hit = True\n                    self.model._structure_cache_hits += 1\n                    return\n            except Exception:\n                # Numeric scenario state may make a structurally valid cached\n                # candidate unusable. Fall through to a full compile; never\n                # mutate or evict the shared candidate because of one scenario.\n                pass\n        self._structure_cache_hit = False\n        self.model._structure_cache_misses += 1\n        self._compile_with_pruning()\n        # Do not cache a plan whose structure was obtained by pruning a numeric\n        # evaluability failure; that would poison later scenarios with the same\n        # supplied/fixed signature.\n        if not self._unevaluable_names:\n            self.model._structure_cache.setdefault(fingerprint, self._capture_structure())\n\n'''
text = text[:pos] + helpers + text[pos:]

# Model cache bookkeeping.
old = '''        self._structure_cache: dict[tuple[frozenset[str], frozenset[str]], Any] = {}\n'''
new = '''        self._structure_cache: dict[\n            tuple[frozenset[str], frozenset[str]], _CompiledStructure\n        ] = {}\n        self._structure_cache_hits = 0\n        self._structure_cache_misses = 0\n'''
if old not in text:
    raise SystemExit('model structure cache declaration not found')
text = text.replace(old, new, 1)

path.write_text(text)

# Cache contract tests.
test = Path('tests/test_relation_system_compile_plan.py')
t = test.read_text()
t += '''\n\ndef test_same_structure_reuses_model_cache_with_fresh_values():\n    model = _model()\n    first = model.compile(inputs={"R": 6.0, "a": 2.0}, fixed={"R"})\n    assert not first._structure_cache_hit\n    misses = model._structure_cache_misses\n    second = model.compile(inputs={"R": 9.0, "a": 3.0}, fixed={"R"})\n    assert second._structure_cache_hit\n    assert model._structure_cache_hits == 1\n    assert model._structure_cache_misses == misses\n    assert second.inputs["R"] == 9.0\n    assert second.inputs["a"] == 3.0\n\n\ndef test_changed_fixed_signature_compiles_new_structure():\n    model = _model()\n    model.compile(fixed={"R"})\n    second = model.compile(fixed={"R", "a"})\n    assert not second._structure_cache_hit\n    assert len(model._structure_cache) >= 2\n'''
test.write_text(t)
print('added model-owned structural cache with numeric validation fallback')
